use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut result = Vec::new();
    let mut last_key = None;

    for line in input.as_array() {
        let mut row = line.as_array();
        let key = row.get(0).map(|v| v.as_i64().unwrap()).unwrap();
        let value = row.get(1).map(|v| v.as_i64().unwrap()).unwrap();

        if last_key.is_none() || key != last_key {
            result.push(vec![key, value]);
            last_key = Some(key);
        }
    }

    serde_json::Value::Array(result)
}
